00	6	DC.W 300	7	DC.W 300	8	DC.W 300	9widths640	DC.W 200	1	DC.W 228	2	DC.W 300	3	DC.W 352	4	DC.W 400	5	DC.W 452	6	DC.W 500	7	DC.W 552	8	DC.W 600	9;; --- New window parameter list offsets	----------------------------;p_length	equ 0	Number of bytes in parameter list.p_wframe	equ p_length+2	Type of window, frame flags.p_wtitle	equ p_wframe+2	Pointer to window's title.p_wrefCon	equ p_wtitle+4	Reserved for application.p_wfull	equ p_wrefCon+4	Size of window, used with ZoomWindow.p_wcolor	equ p_wfull+8	Pointer to window's color table.p_y_origin	equ p_wcolor+4	Content's vertical offset.p_x_origin	equ p_y_origin+2	Content's horizontal offset.p_data_h	equ p_x_origin+2	Height of total data area.p_data_w	equ p_data_h+2	Width of total data	area.p_wmaxheight	equ p_data_w+2p_wmaxwidth	equ p_wmaxheight+2p_vscroll	equ p_wmaxwidth+2	Amount to scroll vertically (arrows).p_hscroll	equ p_vscroll+2	Amount to scroll horizonally (arrows).p_vpage	equ p_hscroll+2	Amount to page vertically (page region).p_hpage	equ p_vpage+2	Amount to page horizontally (page rgn).p_wInfoText	equ p_hpage+2p_wInfoH	equ p_wInfoText+4	Height of infomation bar.p_wdefProc	equ p_wInfoH+2	NOT USED.p_wInfoDraw	equ p_wdefProc+4	Address of routine to draw Info Bar.p_updateDraw	equ p_wInfoDraw+4	Address of routine to draw content region.p_position	equ p_updateDraw+4p_behind	equ p_position+8p_windrec	equ p_behind+4p_size	equ p_windrec+4	ENDP****************************************************************** ErrorWindow** Description	This call displays an alert window containing*	standard system error messages.  ** Inputs:*	Previous contents*	Result space	WORD*	Sub. Strng. Type	WORD  0 = C string, 1 = Pascal*	Pointer to sub mess	LONG*	Error number	WORD** Outputs:*	Previous contents*	Result	WORD  Button number selected*****************************************************************	longa on	; mode	longi onErrorWindow   	PROC EXPORT	DefineStackOrigD	wordHexString	longTerminator	wordTemp	longRet1	block 3Ret2	block 3ErrorNum	wordsubstrgs	longstrgType	wordresult	word	jsl IncBusyFlg	lda #0	;Cstring terminator	pha	pha	;room hex string	pha	pha	;temp	pha	phd	tsc	tcd;; Call SysBeep2 if the error code is 0..FF;	lda <errorNum	and #$ff00	beq @inRange	lda #$CEFF	bra @thisBeep@inRange	lda <errorNum	ora #$CE00	;default silent, defer to GNE, beep $0Exx@thisBeep	pha	_SysBeep2;; Set up for the alert window call;	pha	;space for result*** Force the cool button position bit on	lda <strgType	ora #$0020	pha;; Alert Window wants a pointer to a table of pointers for the substitution strings.;  Since we only allow one substitution, item 0, we simply need a pointer to a pointer.;  We are passed a pointer, so we pass a pointer to the pointer we are passed.;	pea $0000	;msw of pointer to pointer	tdc	clc	adc #substrgs	;lsw of pointer to pointer	pha;; Make LoadResource call to get error message;	pha	;space for result	pha	pea $8020	;Resource ID type: rErrorString	pea $07FF	;msw of error is 0	pei <ErrorNum	;21-Sep-90 DAL	_LoadResource	bcc NoRezLoadError;; Error in load resource.  Clean stack and display 'unknown error' message;	tax	;save error number	pla	;clean stack	pla	pla	pla	pla	pla;; Start over: first create hex error number and a pointer to it;	pha	;space for result	pha	pei <ErrorNum	;21-Sep-90 DAL	_HexIt	;leaves 4 byte hex string on stack	pla	sta <HexString	pla	sta <HexString+2;;create pointer to string and put it in substrgs;	lda #0	sta <substrgs+2	;msw is 0 since its on the stack	tdc	clc	adc #HexString	sta <substrgs;; Set up for the alert window call;	pha	;space for result	pea $0020	;C string, cool button position (10-Oct-91 DAL);; Create a pointer to the error number and pass it to alert window;	pea $0000	;msw of pointer error number	tdc	clc	adc #substrgs	;lsw of pointer to pointer	pha;; Make LoadResource call to get unknown error message;	pha	;space for result	pha	pea $8020	;Resource ID type: rErrorString	pea $07FF	;msw of error is 0	pea $0072	;optimized 21-Sep-90 DAL	_LoadResource	bcc NoRezLoadError	;; Error in loading unknown error resource.  Clean stack and exit;LoadError	tax	;save error number	pla	;clean stack: resource handle	pla	pla	;remove sub string pointer	pla		pla	;string type	pla	;result space	bra ErrorExitNoRezLoadError	pla	sta temp	;handle to resource	pla	sta temp+2	ldy #4	lda [<temp],y	ora #$8000	;lock it	sta [<temp],y	dey	dey	lda [<temp],y	pha	;pass pointer to error message	lda [<temp]	pha	_AlertWindow	tax	pla	sta <result	ldy #4	lda [<temp],y	and #$7FFF	sta [<temp],y	;unlock handle	phx	;save error message;; setup for release resource call;	pea $0003	;most purgeable	pea $8020	;resource type	pea $07FF	pei <ErrorNum	;optimized 21-Sep-90 DAL	_ReleaseResource	plx	;restore error message	errorExit	lda <Ret1+4	;Move return address down stack.	sta <result-2	lda <Ret1+2	sta <result-4	lda <Ret1	sta <result-6	pld	pla	;temp work area	pla	pla	;hex string	pla	;hex string	pla	;0 terminator		pla	;remove input parameters froms stack	pla	pla	pla	phx	;error result from AlertWindow		jsl DecBusyFlg	pla	;get error result	cmp #1	;21-Sep-90 DAL (was CMP #0)		rtl	ENDP;===================================================;	Compile string.;===================================================;;   IN:    PUSH:LONG - space for result, handle of compiled string.;          PUSH:WORD - 0 if substitution strings are C type	(null or return).;	   1 if substitution strings are Pascal	type (length byte).;          PUSH:LONG - pointer to substitution strings.;          PUSH:LONG - pointer to source string.;          PUSH:WORD - size of source string.;;  OUT:    Carry clear, handle of compiled string on stack. Handle size is size of text.;          Carry set if error, a = error code (compileTooLarge = compiled string too large).;; Any '#' followed by an ASCII digit character with be substituted with a standard string; defined in AlertWindow documentation.  Any '*' character followed by an ASCII digit ; character with be substituted with its corresponding string in the given substitution; array.  If no * substitutions are in the string the pointer to the substitution array; can be any value including nil.;; Characters # and * can be made part of the compiled string by having them twice in the; source string.;CompileString	PROC EXPORTsrcIndex	equ 1desIndex	equ srcIndex+2desSize	equ desIndex+2ptr	equ desSize+2ptr2	equ ptr+4saveDpage	equ ptr2+4saveDbank	equ saveDpage+2returnAddr	equ saveDbank+1inputs	equ returnAddr+6srcSize	equ inputssrcStrg	equ srcSize+2substrgs	equ srcStrg+4strgType	equ substrgs+4result	equ strgType+2	phb	Save caller's data bank pointer.	phd	Save caller's direct page pointer.	tsc	Swtich to direct page in stack.	sec	sbc #saveDpage-1	tcs	tcd	phk	Switch data bank to	program bank.	plb;;; --- Allocate memory for text string ------------------------;	ldx #0	Common need.	pha	Space for result.	pha	phx	Pass number of bytes to allocate.	lda <srcSize	sta <desSize	pha***	pea $1001	Pass ID to use.	pea $400e	;21-Sep-90 DAL	phx	Pass attributes, anywhere, anyhow.	pha	Pass address (not used).	pha	_NewHandle	pla	sta <result	pla	sta <result+2;	jsr derefHand	ptr = (handle);	stz <desIndex	Start storing into first byte in destination.	stz <srcIndex;;; --- Compile text string.;@lop1	jsr fetchSrcChar	Fetch next source character.	bcs @done	All done?;;; ------ Substitute standard string?;	cmp #'#'	Substitute standard	string character?	bne @next1;	jsr fetchDigit	Fetch which standard string to use.	bcs @store1	Next character a digit?;	asl a	Substitute standard	string.	tax	lda |standButts,x	sta <ptr2	lda #standButts>>16	sta <ptr2+2	jsr Ctype	Move standard string into text.	bcc @lop1	Get next character if buffer not full.	bra @errorOut	Buffer is full.;;; ------ Speical subsitution character?;@next1	cmp #'*'	Speical subsitution	character?	bne @store1;	jsr fetchDigit	Fetch which subsitute string to use.	bcs @store1	Next character a digit?;	jsr storeSub	Store substitution string in text.	bcc @lop1	Get next character if buffer not full.	bra @errorOut	Buffer is full.;;@store1	jsr storeChar	Store character in destination buffer.	bcc @lop1;;; --- Error exit.;@errorOut	pha		Save error code.;	pei <result+2	Pass handle of destination buffer.	pei <result	_DisposeHandle	Free destination buffer.	stz <result	Return NIL handle.	stz <result+2	ply		Restore error code.	bra @exit;;; --- Clean up stack and exit.;@done	pea 0	Set compiled string handle to size of text.	pei <desIndex	pei <result+2	pei <result	_SetHandleSize	ldy #0	No error.@exit	lda <returnAddr+4	sta <result-2	lda <returnAddr+2	sta <result-4	lda <returnAddr	sta <result-6	tsc	Free temp direct page.	clc	adc #saveDpage-1	tcs	pld	Restore caller's direct page pointer.	plb	Restore caller's data bank pointer.	tsc	Remove input parameter from stack.	clc	adc #result-inputs	tcs	tya	Return error code in a.	cmp #1	Set error flag.	rtl;------------------------------------------------------------------------------;	Fetch a character from source buffer.;------------------------------------------------------------------------------;;    IN: <srcStrg = pointer to source buffer.;        <srcIndex = index to next character in source buffer.;        <srcSize = size of source buffer.;;   OUT: <srcIndex = incremented to next character.;        Carry clear if a = character in low byte, high byte = zero.;        Carry set if no more characters.;fetchSrcChar	ldy <srcIndex	cpy <srcSize	bcs @exit	;No more characters?	lda [<srcStrg],y	and #$00FF	inc <srcIndex	clc	;Character fetched flag.@exit	rts;-------------------------------------------------------------;          Fetch and convert a ASCII decimal digit.;-------------------------------------------------------------;;    IN: <srcStrg = pointer to source buffer.;        <srcIndex = index to ASCII decimal digits.;;  OUT:  <srcIndex = next character.;        Carry clear, a = digit.;        Carry set, a = character that wasn't a decimal digit.;fetchDigit	jsr fetchSrcChar	;Fetch the next character.	bcc @ok1	;No more characters?	lda #0	;Return null character.@notDigitExit	sec	rts@ok1	cmp #'0'	;Is the next character a digit?	bcc @notDigitExit	cmp #'9'+1	bcs @notDigitExit*** CARRY IS CLEAR***	sec***	sbc #'0'***	clc	;a = digit.	and #$000f	;opt 21-Sep-90 DAL* CARRY IS CLEAR FROM ABOVE	rts;------------------------------------------------------------------------------;	Store character into destination buffer.;------------------------------------------------------------------------------;;   IN: a = character to store, only the low byte used.;       <desPtr = pointer to destination buffer.;       <desIndex = index to where to store character in destination buffer.;       <desSize = size of destination buffer.;;  OUT: Carry set if error, a = error code (1=des too large).;       Destination buffer may have had to be resized.  If so, handle is dereferenced again.;storeChar	ldy <desIndex	;Is there room in the destination buffer?	cpy <desSize	bcc @ok1;;; --- Grow the destination buffer.;	pha		Save character to store.	lda <desSize	Increase destination buffer size.	clc	adc #256	bcc @ok2	lda #$0E04		Error, destination too large.;			(compileTooLarge not available)@errorOut	plx		Clean up stack.	rts@ok2	sta <desSize	New buffer size.	pea 0	Pass new size.	pha	pei <result+2	Pass handle of destination buffer.	pei <result	_SetHandleSize	bcs @errorOut	jsr derefHand	Dereference destination buffer.	pla		Restore character to store.;;; --- Store the character.;@ok1	ldy <desIndex	sep #$20	Go to 8 bit.	LONGA OFF	sta [<ptr],y	Store character in destination buffer.	rep #$20	Back to 16 bit.	LONGA ON	inc <desIndex	Increment destination index.	clc	No error.	rts;;;------------------------------------------------------------------------------;	Move string into destination text.;------------------------------------------------------------------------------;;   IN:    a = substitution string number.;          <subStrgs = pointer to array	of string pointers.;          <ptr = pointer to destination string.;          <work = length counter of destination string.;          <strgType = 0 if C sub strings, 1 if Pascal sub strings.;;  OUT:    Carry set if buffer full.;storeSub	asl a	Compute index.	asl a	tay	lda [<subStrgs],y	Get pointer to subsitute string.	sta <ptr2	iny	lda [<subStrgs],y	sta <ptr2+1	lda <strgType	C type string?	beq Ctype;;; --- Pascal type string -------------------------------------;	lda [<ptr2]	Get number of bytes	in string.	and #$00FF	beq @exit1	tax	ldy #1@lop1	lda [<ptr2],y	and #$00FF	phy	phx	jsr storeChar	plx	ply	bcs @exit2	iny	dex	bne @lop1@exit1	clc@exit2	rts;---------------------------------------------------------------;	Insert C type string.;---------------------------------------------------------------;;   IN: <ptr2 = pointer to C string to insert.;Ctype	ldy #0@lop1	lda [<ptr2],y	and #$00FF	beq @exit1	End of substitution	string?	iny	phy	jsr storeChar	ply	bcc @lop1	rts@exit1	clc	Buffer OK.	rts;---------------------------------------------------------------;	Dereference handle.;---------------------------------------------------------------;derefHand	ldy #2	lda [<result],y	sta <ptr+2	lda [<result]	sta <ptr	rts;;; --- Standard button strings --------------------------------;standButts	dc.w OK	0	dc.w Cancel	1	dc.w Yes	2	dc.w No	3	dc.w TryAgain	4	dc.w Quit	5	dc.w Continue	6	dc.w Bad	7	dc.w Bad	8	dc.w Bad	9	STRING ASISOK	dc.b 'OK',0	export Cancel	;6-Dec-91 DALCancel	dc.b 'Cancel',0Yes	dc.b 'Yes',0No	dc.b 'No',0TryAgain	dc.b 'Try Again',0Quit	dc.b 'Quit',0Continue	dc.b 'Continue'Bad	dc.b 0	ENDP************************************************************************ $630E GetAuxWindInfo -- new call 19-Jan-91 DAL** Input:*   space for result (LONG)*   window pointer   (LONG)** Uses <auxInfoHandle on Window Manager direct page.  If it's NIL,* we allocate it for the first time.** If we don't find the window we're looking for, we need to grow the* handle to make more room.** The AuxWindHandle block has this structure:*   +000: number of aux window record that will fit in the handle*   +002: number of aux window records really in the list*   +004: first record*   +xxx: ...* Each record has the form:*   -004:window pointer*   +000:size in bytes*   +002:bank register value (low byte of word)*   +004:data register value*   +006:resource app value*   +008:old update region handle*   +012:old port (for EndUpdate)*   +016:window layer (for Windoid support) (LONG)*   +020:min vertical size for window (used only for system windows?)*   +022:min horizontal size for window (used only for system windows?)*   +024:NDA Structure Pointer (points to what's handy for the Desk Mgr)*   +028:(size of record)***********************************************************************GetAuxWindInfo	proc export	export KillAuxInfoRecord	export DerefMyhandle	export IncResultBy4auxWindRecSize	equ 28+4	;size includes window pointerauxWindUserSize	equ 28	;34 bytes in the user-visible areaGrowByNWindows	equ 5	;grow the list 10 windows at a timeDirPagePtr	equ 1myPtr	equ DirPagePtr+4myHandle	equ myPtr+4oldD	equ myHandle+4rtl	equ oldD+2windPtr	equ rtl+6result	equ windPtr+4	phd	pha	pha	;space for myHandle	pha	pha	;space for myPtr	phy	pha	;push direct-page pointer on stack frame	tsc	tcd		stz <result+2	stz <result	jsr GetAuxPointer	ldy #2	lda [<myPtr],y	;number of entries in the list	beq @noMatch	tax	;keep the count in X	ldy #4@scan	lda [<myPtr],y	iny	iny	cmp <windPtr	bne @tryNext	lda [<myPtr],y	cmp <windPtr+2	bne @tryNext	iny	iny	tya	clc	adc <myPtr	sta <result	lda <myPtr+2	bcc @1	inc a@1	sta <result+2	brl @exit@tryNext	dey	dey	tya	clc	adc #auxWindRecSize	tay	dex	bne @scan** No matching entry found--allocate another one, clean it out, and return* the pointer.** May need to grow the handle to make room.*@noMatch	ldy #2	lda [<myPtr],y	;number of entries in list	cmp [<myPtr]	;equal to number that will fit?	bcc @itFits	pha	pha	;space for _Multiply result	clc	lda [<myPtr]	adc #GrowByNWindows	sta [<myPtr]	pha	pea auxWindRecSize	_Multiply*** added 28-Feb-91 DAL--Oops, I forgot to add 4 for the header stuff	pla	plx;	clc	;carry is already clear	adc #4	bcc @coolBeans	inx@coolBeans	phx	pha*** end of 28-Feb-91 DAL	pei <myHandle+2	pei <myHandle	_SetHandleSize	;this had better work....	jsr DerefMyHandle	;maybe it moved when we grew it	ldy #2	lda [<myPtr],y	;get entry count back in A@itFits	inc a	sta [<myPtr],y	;increment count of entries in list	pha	pha	;space for _Multiply result	dec a	pha	;zero-based index to new entry	pea auxWindRecSize	_Multiply	clc	pla	adc <myPtr	sta <result	pla	adc <myPtr+2	sta <result+2	jsr IncResultBy4	lda <windPtr	sta [<result]	ldy #2	lda <windPtr+2	sta [<result],y	jsr IncResultBy4	lda #0	ldy #auxWindUserSize-2  ;oops, was auxWindRecSize! 3-Mar-91 DAL@clear	sta [<result],y	dey	dey	bne @clear	lda #auxWindUserSize	sta [<result]	;set up the user-visible record size word@exit	pla	pla	;pulled direct-page pointer	pla	pla	;pulled myPtr	pla	pla	;pulled myHandle	pld	;restored D	ldx #0	ldy #4	jml $e10184	;ToStrip** GetAuxPointer -- allocate the AuxInfoHandle if necessary, and return*   myHandle, myPtr.*GetAuxPointer	ldy #AuxInfoHandle+1	lda [<DirPagePtr],y	bne @allocated	pha	pha	;space for handle	pea 0	pea GrowByNWindows*auxWindRecSize+4	ldy #MyID	lda [<DirPagePtr],y	pha	;mem id	pea 0	;attributes	pha	pha	;location unused	_NewHandle	pla	ldy #AuxInfoHandle	sta [<DirPagePtr],y	sta <myHandle	pla	iny	iny	sta [<DirPagePtr],y	sta <myHandle+2*** Initialize the new handle	jsr DerefMyHandle	lda #GrowByNWindows	;init the how-many-fit field	sta [<myPtr]	ldy #2	lda #0	;init the how-many-there-are field	sta [<myPtr],y	@allocated	ldy #AuxInfoHandle	lda [<DirPagePtr],y	sta <myHandle	iny	iny	lda [<DirPagePtr],y	sta <myHandle+2	jsr DerefMyHandle	rtsDerefMyHandle	ldy #2	lda [<myHandle]	sta <myPtr		lda [<myHandle],y	sta <myPtr+2	rtsIncResultBy4	clc	lda <result	adc #4	sta <result	bcc @1	inc <result+2@1	rts************************************************************************ KillAuxInfoRecord -- new subroutine 20-Jan-91 DAL** Input:*   PUSH Window Pointer (LONG)*   JSL KillAuxInfoRecord** (This is a subroutine, not a tool call)** Direct page must be set to the Window Manager***********************************************************************KillAuxInfoRecord@DirPagePtr	equ 1@myPtr	equ @DirPagePtr+4@myHandle	equ @myPtr+4@oldD	equ @myHandle+4@rtl	equ @oldD+2@windPtr	equ @rtl+3	phd	pha	pha	;space for myHandle	pha	pha	;space for myPtr	pea 0	phd	;push direct-page pointer on stack frame	tsc	tcd	jsr GetAuxPointer	;creates it if necessary	ldy #2	lda [<myPtr],y	beq @exit	;no aux window records--just leave	tax	ldy #4	;offset to first record@scan	lda [<myPtr],y	iny	iny	cmp @windPtr	bne @tryNext	lda [<myPtr],y	cmp @windPtr+2	beq @foundIt@tryNext	dey	dey	tya	clc	adc #auxWindRecSize	tay	dex	bne @scan@exit	pla	pla	;pulled direct-page pointer	pla	pla	;pulled myPtr	pla	pla	;pulled myHandle	pld	;restored D	lda 2,s	sta 2+4,s	lda 1,s	sta 1+4,s	pla	pla	rtl** Found the matching aux window record at myPtr+Y.  Squish* the rest of them in and decrement the total count.*@foundIt	dey	dey	tya	clc	adc #auxWindRecSize	sta >@minusSize	adc <myPtr	tax	lda <myPtr+2	adc #0	pha	phx	;pushed pointer to the next record	clc	tya	adc <myPtr	tax	lda <myPtr+2	adc #0	pha	phx	pha	pha	;space for GetHandleSize	pei <@myHandle+2	pei <@myHandle	_GetHandleSize	sec	lda 1,s	sbc >@minusSize	sta 1,s	;size to copy (remaineder of record)	_BlockMove	ldy #2	;decrement number-of-entries count	lda [<myPtr],y	dec a	sta [<myPtr],y	bra @exit@minusSize	dc.w 0	endp************************************************************************ $640E DoModalWindow -- new call 22-Jan-91 DAL** Input:**** First, a little about fakeModalDialog:** fakeModalDialog returns a long as a result.* If the result is NULL:*     Nothing happened.  Unlike ModalDialog, control is returned to*     the application during null events.  This is so the application*     can do stuff like switch cursors, or other idle tasks.* If bit 31 of the result is true:*     The user chose a menu item.  Bits 0-15 are the menu item ID.*                                  Bits 16-30 are the menu ID.* If bit 31 of the result is false:*     The user clicked on a control.  Bits 0-30 are the control ID.** Now, the sample code fragment:**   #define aboutBoxID 0x1001L**   void    doAboutBox()*   {*       WindowPtr       wptr, keepPort;*       unsigned long   id;*       unsigned int    item;*       keepPort = GetPort();   /* Preserve the current port. */**       wptr = NewWindow2(NULL, NULL, NULL, NULL, 2, aboutBoxID, rWindParam1);*           /* Open the about box from a resource. */**       if (!_toolErr) {            /* If the window opened successfully... */*           aboutWindow = wptr;     /* Set the aboutWindow global variable. */*                                   /* This tells other routines what state */*                                   /* we are in.                           */**           for (;;) {      /* Loop, due to NULL events being returned. */**               id = fakeModalDialog(*                   &event,         /* Pointer to extended event record.   */*                   NULL,           /* Use default update procedure.       */*                   NULL,           /* There will be no event mods.        */*                   NULL,           /* Do standard beep.                   */*                   mwMenuSelect+   /* Allow pullDowns.                    */*                   mwMenuKey+      /* Allow menu keys.                    */*                   mwDeskAcc+      /* Allow desk accessories.             */*                   mwUpdateAll     /* Update all windows, not just about. */*               );**               item = id;          /* Get lo-word from result. */**               if (id & 0x80000000L) {             /* If menu command...    */*                   if (item == 255) {              /* If close command then */*                       HiliteMenu(0, FileMenuID);  /* turn menu inv. off.   */*                       break;                      /* Go close about box.   */*                   }*                   doMenuCommand(id);      /* Do other menus (like quit).   */*                   if (quitFlag) break;    /* User did do a quit from menu. */*               }*               else {                          /* ...else handle controls. */*                   if (item == 1) break;       /* User clicked OK button.  */*               }*           }**           SetPort(keepPort);      /* Put port back before closing about. */*           CloseWindow(wptr);      /* Close aboutBox.                     */*           aboutWindow = NULL;     /* Let others know it is closed.       */*           appSetMenus();          /* Update the menus to reflect a new.  */*       }                           /* top window.                         */*   }***********************************************************************DoModalWindow	proc export	entry theIBeamAdr	import ctlPart	import doInitCursor	;14-Nov-91 DALfVis	equ $0020	;visible bit in window framemwNoScrapForLE	equ $0001mwMenuSelect	equ $0002mwMenuKey	equ $0004mwIBeam	equ $0008mwDeskAcc	equ $0010mwWantActivate	equ $0020	;added 20-May-91 DALmwUpdateAll	equ $4000mwMovable	equ $8000	DefineStackdlgwptr	long	;Must be at 1,skeepPort	long	;Must be at 5,sctlHndl	longctlPtr	longtheHndl	longthePtr	longwhichWindow	longtempwptr	longcode	wordeditTask	wordyloc	wordxloc	wordwkind	wordmenunum	wordzero	wordsizeLocals	EndLocalssaveDPage	wordreturnAddr	block 6	;was 3 (DAL)	BegParmsflags	wordbeepProc	long	;Null, SysBeep.  Negative, do nothing.eventHook	long	;Optional -- pass a NULL for none.updateProc	long	;Optional -- pass a NULL for default.event	long	;Must be extended 5.0 event rec ptr.sizeParms	EndParmsretval	long	;Control ID hit.  NULL if none.		;If bit 31 is on, then retval		;is a menu ID.	lda #0	;added 18-Apr-91 DAL	sta >ctlPart	;added 18-Apr-91 DAL	phd	;Save directPage register.	tsc	;Make space for locals.	sec	sbc #sizeLocals	tcs	tcd	;Set directPage register.	pla	pla	_GetPort	;Result space already there (keepPort).	pha	pha	_FrontWindow	;Result space already there (dlgwptr).	pha	;Find out if it is a DA window.	pei dlgwptr+2	pei dlgwptr	_GetWKind	pla	sta wkind	bpl @gotit@get1stRegWnd	pha	;Result space for _GetWFrame.	pha	;Result space for _GetNextWindow.	pha	pei dlgwptr+2	pei dlgwptr	_GetNextWindow	lda 1,s	;Param for _GetWFrame.	sta dlgwptr	lda 3,s	sta dlgwptr+2	_GetWFrame	pla	and #fVis	beq @get1stRegWnd	;Window is invisible, so skip it.	pha	pei dlgwptr+2	pei dlgwptr	_GetWKind	pla	bmi @get1stRegWnd	;Window is system window, so skip it.@gotit	stz retval	;Assume nothing interesting is	stz retval+2	;going to happen.	stz code	stz editTask	;For cut/copy/paste/clear signal.	stz zero	;For optimization purposes.*** Note that updateProc+3 can have flag bits set	lda updateProc+1	;Set up the update procedure for all	bne @a	;cases.  This also sets it up so that		;TaskMaster can handle this window		;from other parts of the application.*** added 10-Jul-92 DAL -- See if the window already has a wContDraw procedure	pha	pha	pei <dlgwptr+2	pei <dlgwptr	_GetContentDraw	pla	plx	bne @aa	tax	bne @aa*** end 10-Jul-92	lda #doStdDrawProc>>16;;;	sta updateProc+2*** 10-Jul-92 DAL -- OR in so we don't mess up the no-GS/OS-needed flag bit (bit 30)	tsb updateProc+2*** end 10-Jul-92	lda #doStdDrawProc	sta updateProc	;Use the default update procedure.@a*** added 10-Jul-92 DAL -- assume modal windows are always smart about B/D/ResApp/CtlParamPtr	lda #$8000	tsb <updateProc+2*** end 10-Jul-92	pei updateProc+2	pei updateProc	pei dlgwptr+2	pei dlgwptr	_SetContentDraw	;Let the window and TaskMaster know.@aa	pha	;Make sure that top window is	pha	;the active window.	_GetPort	pla	sta keepPort	pla	sta keepPort+2	pei dlgwptr+2	pei dlgwptr	_SetPort	lda flags	and #mwIBeam	beq @b	;No cursor changes.	lda wkind	bmi @b	pha	;Result space for control part.	ldy #0	;Point to where to put the handle.	phy	tdc	clc	adc #ctlHndl	pha	;Pointer to ctlHndl now on stack.	phy	adc #yloc-ctlHndl	pha	;Pointer to yloc now on stack.	_GetMouse	pei xloc	;Now that they are right, pass 'em on.	pei yloc	pei dlgwptr+2	pei dlgwptr	_FindCursorCtl	;Find which control cursor is over.	pla	;The part code, which we don't care		;about here.	beq @arrowCursor	;Not over any control -- use arrow.	jsr getCtlProc	;Find out what kind of control it is.	cmp #editTextControl>>16	beq @ibeamCursor	;It is a TextEdit ctl, kind of		;See fmdFindCursorCtl for more info.	cmp #editLineControl>>16	beq @ibeamCursor	;It is a LineEdit tool.@arrowCursor	jsr ibeamTest	bcc @b	jsr doInitCursor	;14-Nov-91 DAL	bra @b	;We have an arrow cursor.@ibeamCursor	jsr ibeamTest	bcs @b	;We have an ibeam cursor.	_IBeamCursor	pha	pha	_GetCursorAdr	pla	sta >theIBeamAdr	pla	sta >theIBeamAdr+2@b	_SystemTask	lda flags	;See if cut/copy/paste is tied to menu.	and #mwMenuSelect+mwMenuKey	beq @c	;Isn't keyDownEvt or mouseDownEvt.	_MWSetUpEditMenu	;Update the edit menu.@c*** added 21-Apr-91 DAL -- to let sounds happen right, do our update before*** calling GetNextEvent allowing mouse and key events@eventAgain	pha	pea $0140	;update and activate events only	pei <event+2	pei <event	_GetNextEvent	pla	beq @noSpecialUpdate	lda [<event]	cmp #8	       ;8=activate	beq @handleSpecialUpdate   ;munch other window's deactivate event; (event must be an update, #6)*** compare middle word of window ptr	ldy #3	;middle word of message field	lda [<event],y	cmp <dlgwptr+1	beq @handleSpecialUpdate@noSpecialUpdate*** end of 21-Apr-91 DAL	pha	;Get the event.	pea $0FFF	;was $FFFF 17-Feb-91 DAL	pei event+2	pei event	_GetNextEvent	pla	beq @exit	;Event shouldn't be handled by app.@handleSpecialUpdate	lda [event]	sta code	bne @gotEvent@exit	lda code	;See if code is 0.  If it is, force a	bne @exit0	;NULL event, so the cursor will flash	sta [event]	;for lineedit items, etc.	pha	pea 1	pha	pha	pei event+2	pei event	_SendEventToCtl	pla@exit0	pei keepPort+2	pei keepPort	_SetPort	tsc	;Get rid of local variables.	clc	adc #sizeLocals	tcs	pld	;Restore directPage register.	ldx #0	ldy #sizeParms	jml $e10184	;ToStrip@gotEvent	jsr XlateApplePeriod	lda eventHook+1	beq @noEventHook	;Zero, no event massaging.	pei event+2	;Give the event hook something	pei event	;to play with.	phk	;Push where we want to return to.	pea @noEventHook-1	pha	;Push the eventHook address and return	phb	;to it.	pla	lda eventHook	dec a	pha	rtl@noEventHook	lda [event]	sta code	jsr doMouseDown	bcc @exit	jsr doMenuKey	bcc @exit	;The key was a menu key.	jsr doCutCopyPaste	bcc @exit	;We did a cut, copy, or paste.	jsr doActivate***	bcc @exit	;We did an activate.*** added 20-May-91 DAL	bcs @didNotActivate	lda <flags	and #mwWantActivate	