routine when* it gets an activate event, make a call to fmdSetMenuProc.  For an application* menu update routine called appSetMenus, you would tell fakeModalDialog* about it by the following:*     ignore = fmdSetMenuProc(appSetMenus);* To turn off menu updating again, do this:*     ignore = fmdSetMenuProc(NULL);***********************************************************************MWSetMenuProc	proc exportnewProc	equ 7	;on stackresult	equ newProc+4	;on stack	lda >menuProc+2	sta result+2,s	lda >menuProc	sta result,s	lda newProc+2,s	inc a	beq @noChange	;$FFFFxxxx = keep old value	dec a	sta >menuProc+2	lda newProc,s	sta >menuProc@noChange	ldx #0	;no error	ldy #4	;strip 4 bytes of input	jml $e10184	;ToStrip	export MenuProcMenuProc	dc.l 0	EndP************************************************************************ $670E MWStdDrawProc -- new call 22-Jan-91 DAL** Input: none** Window to draw is current port.  We always draw the controls, and* we may also draw our own "alert" type frame inside the content.***********************************************************************MWStdDrawProc	proc export	pha	;What kind of window frame do we want?	pha	pha	_GetPort	_GetWFrame	pla	;fAlert is bit 13.  fFlex is bit 9.	asl a	asl a	;fAlert is now in bit 15.	bmi @noFrame	;We already have a frame, and		;it looks maaahvelous!	and #$0800	;Bit 9 moved into bit 11.	bne @noFrame	pha	_GetMasterSCB	pla	xba	asl a	lda #5	bcs @in640	lsr a@in640	pha	;Keep the width for _InsetRect.	pha	;Push the width for _FrameRect.	pea 2	_SetPenSize	plx	;The width for _InsetRect.	lda #@workRect	ldy #@workRect>>16	phy	;Push parameters for _FrameRect.	pha	phy	;Push parameters for _InsetRect.	pha	phx	;Push the width for _InsetRect.	pea 2	phy	;Push parameters for _GetPortRect.	pha	_GetPortRect	_InsetRect	_FrameRect	_PenNormal@noFrame	pha	pha	_GetPort	_DrawControls	rtl@workRect	ds.w 4	EndP************************************************************************ $680E MWSetUpEditMenu -- new call 19-Jan-91 DAL** Input:*** fmdEditMenu figures the state of cut, copy, paste, and clear in* the edit menu based on the state of controls in the window.* It looks up the target control (either lineEdit or textEdit) and* then sets the states appropriately.  For lineEdit, if anything* is selected, then cut, copy and clear are available.  If there is* anything in the scrap, then paste is also available.  TextEdit * works the same way, unless the textEdit control is a read-only* control.  In that case, cut, paste, and clear are not available.* If there is no lineEdit or textEdit control, then the state of* these menu items is left alone.  The application needs to take care* of them in that case.  (It is possible that there are custom* controls for the application that can use these menu items, and* there is no way for fakeModalDialog to know about them.  Therefore* the correct thing to do is to do nothing.)***********************************************************************MWSetUpEditMenu	proc export	DefineStackselStart	longselEnd	longleHndl	longlePtr	longctlPtr	long	;Must be 2nd from end of local space.ctlHndl	long	;Must be at end of local space.sizeLocals	EndLocalssaveDPage	wordreturnAddr	block 6	;was 3 (DAL)	phd	;Save directPage register.	tsc	;Make space for locals, part 1.	sec	sbc #sizeLocals	tcd	pha	;Find out if it is a DA window.	pha	pha	_FrontWindow	_GetWKind	pla	bpl @a	;It is a regular window.	pea 250	_EnableMItem	;Enable undo.	pea 255	_EnableMItem	;Enable close.	ldx #%1111	;Enable cut/copy/paste/clear.	brl @setMenus@a	pha	pha	_FindTargetCtl	bcc @aa	;There is a target, so go do some work.	brl @noTool@aa	ldy #2	;Deref target ctl handle into ctlPtr.	lda [ctlHndl],y	pha	lda [ctlHndl]	pha	tdc	;Make space for locals, part 2.	tcs	;Stack ptr & directPage ptr agree now.	ldy #octlProc+2	;Get hi-word of proc address.	lda [ctlPtr],y	cmp #editTextControl>>16	beq @textEdit	;It is TextEdit tool.	cmp #editLineControl>>16	bne @noTool	;Not LineEdit tool.@lineEdit	ldy #octlData	;Get the lineEdit handle from	lda [ctlPtr],y	;the control's data field.	sta leHndl	iny	iny	lda [ctlPtr],y	sta leHndl+2	ldy #2	;Dereference leHndl.	lda [leHndl]	sta lePtr	lda [leHndl],y	sta lePtr+2	ldx #0	jsr canWePaste	ldy #oleSelStart	lda [lePtr],y	iny	iny	cmp [lePtr],y	beq @setMenus	txa	ora #%1011	;Enable cut/copy/clear.	tax		bra @setMenus@textEdit	ldy #0	phy	tdc	clc	adc #selStart	pha	phy	adc #selEnd-selStart	pha	pei ctlHndl+2	pei ctlHndl	_TEGetSelection	ldx #%1011	lda selStart	cmp selEnd	bne @hasSelect	lda selStart+2	cmp selEnd+2	bne @hasSelect	ldx #0@hasSelect	jsr canWePaste	ldy #$28+2	;Find out if we are read-only.	lda [ctlPtr],y	and #$0400	;Bit 26, please.	beq @setMenus	txa	;Don't allow cut & paste.	and #2	tax	bra @setMenus@noTool	ldx #0	;Bit 0 for cut, 1 for copy,		;2 for paste.@setMenus	txa	ldy #251	jsr setOneMenu	jsr setOneMenu	jsr setOneMenu	jsr setOneMenu@exit	tdc	;Remove local space.	clc	adc #sizeLocals	tcs	pld	;Restore directPage register.	lda #0	clc	rtlsetOneMenu	lsr a	pha	phy	phy	bcs @enable@disable	_DisableMItem	bra @a@enable	_EnableMItem@a	ply	iny	pla	rtscanWePaste	txa	;Assume no paste.	and #$FFFF-4	pha	pha	;See if paste should be available.	pha	pea 0	_GetScrapSize	plx	ply	pla	;Get cut/copy/paste status back.	bcs @exit	;Error, so no paste.	phy	ply	bne @yes	txy	beq @exit@yes	ora #4@exit	tax	rts	EndP************************************************************************ $690E FindCursorCtl -- new call 22-Jan-91 DAL** Input:*    LONG  pointer to buffer to receive control handle*    WORD  X position*    WORD  Y position*    LONG  window pointer** FindCursorCtl is used to find which control is at a certain point.* The toolbox call FindControl can't be used for this because TextEdit* controls become active when called with a point in them.  That is not* the desired effect of fmdFindCursorCtl.  If you just want to know what* control you are over and have nothing affected, then use this entry* point.  It is used by fakeModalDialog to determine whether or not to* display an i-beam cursor.  If the i-beam bit is set and the user moves* the mouse over a lineEdit or textEdit control, then the cursor changes* to an i-beam.  Note that the scrollbars for a textEdit control are* considered a separate control.  This is so that the cursor stays* an arrow when over the scrollbars.***********************************************************************FindCursorCtl	proc export	DefineStackhndl	long	;Must be at 1,sctlHndl	longctlPtr	longsizeLocals	EndLocalssaveDPage	wordreturnAddr	block 6	;was 3 (DAL)	BegParmswptr	longyloc	wordxloc	wordctlHndlPtr	long	;Where to store the control handle.sizeParms	EndParmsctlPart	word	phd	;Save directPage register.	tsc	;Make space for locals.	sec	sbc #sizeLocals	tcs	tcd	;Set directPage register.	pei wptr+2	pei wptr	_GetWControls	;Result space already there (hndl).	stz ctlPart	;Assume failure.	stz ctlHndl	stz ctlHndl+2@loop	lda hndl+1	beq @exit	;No more controls to check.	ldy #2	;Deref hndl.	lda [hndl]	sta ctlPtr	lda [hndl],y	sta ctlPtr+2*** added 10-Jun-91 DAL -- see if this control is invisible	ldy #octlFlag	lda [<ctlPtr],y	and #$0080	bne @nextCtl*** end of 10-Jun-91	pha	;Result space for _PtInRect	pea 0	;Push pointer to point.	tdc	clc	adc #yloc	pha	lda ctlPtr	;Push ptr to bounding rect of ctl.	clc	adc #octlRect	tax	lda ctlPtr+2	adc #0	pha	phx	_PtInRect	pla	beq @nextCtl	sta ctlPart	lda hndl	;Copy the temp hndl to the "real" one.	sta ctlHndl	lda hndl+2	sta ctlHndl+2*** added 13-Nov-91 DAL -- no need for special Text Edit handling;;	ldy #octlProc+2	;Get hi-word of proc address.;;	lda [ctlPtr],y;;	cmp #editTextControl>>16;;	bne @exit	bra @exit*** end 13-Nov-91 DAL@nextCtl	ldy #2	lda [ctlPtr]	;Get the next control handle.	sta hndl	lda [ctlPtr],y	sta hndl+2	bra @loop@exit	lda ctlHndl	;Return the ctl hndl (could be NULL).	sta [ctlHndlPtr]	lda ctlHndl+2	ldy #2	sta [ctlHndlPtr],y	tsc	;Get rid of local variables.	clc	adc #sizeLocals	tcs	pld	;Restore directPage register.	ldx #0	;no error	ldy #sizeParms	;number of bytes to strip	jml $e10184	;ToStrip	EndP************************************************************************ $6A0E ResizeInfoBar -- new call 5-Mar-91 DAL** Input:*    WORD  flags (reserved, use 0)*    WORD  new info bar height*    LONG  window pointer** WARNING: This only works for standard windows, not custom windows.***********************************************************************ResizeInfoBar	proc export	phd	tsc	tcd@oldD	equ 1@rtl	equ @oldD+2@window	equ @rtl+6@height	equ @window+4@flags	equ @height+2	ldy #$100-4	;offset to info bar height	lda @height	sta [@window],y	pha	pha	_GetPort	pei @window+2	pei @window	_SetPort	pushlong #ThePortRect	_GetPortRect	_SetPort	sec	lda >ThePortRect+6	sbc >ThePortRect+2	pha	lda >ThePortRect+4	sbc >ThePortRect	pha	pei @window+2	pei @window	_SizeWindow	pld	ldx #0	ldy #8	jml $e10184	;ToStripThePortRect	ds.b 8	EndP********************************************************************************************************************************************** $6B0E HandleDiskInsert -- new call 12-Apr-91 DAL** Input:*   WORD space for result flags*   WORD space for result devnum*   WORD flags*   WORD devNum* Output:*   WORD resultFlags*   WORD resultDevNum** Input flags:*   Bit 15 = perform device scanning*   Bit 14 = perform Volume call & user interaction on errors*   Bit 13 = update the status of a particular device or all devices*   Bit 12 = report any detected disk-ejects too, not just inserts*   Bit 11 = bypass the normal 1-second delay, scan immediately*   Bit 10 = simulate a duplicate-volume error on a specific device*            (set bit 14 also, and pass in devNum)*   Bit  0 = initialize all devices to "offline" status so that each*            device already online will appear as an insertion* * Input devnum: Normally zero.  Pass a nonzero device number if you* already detected an insert & want the system to check it out & possibly* ask the user to format it (flag bit 15 clear, 14 set); or if you are* informing the system that you have already taken care of the new status* of a particular device (flag bit 13 set).* * ResultDevNum: the device number of a device that was inserted or ejected.* Zero if nothing happened, or if the user chose to Eject a disk that was* discovered to be inserted.* * ResultFlags: Bit 0 = set if resultDevNum is an ejection.  Bit 1 = set if* ResultDevNum represents a disk that the user elected to format.* * Implementation notes:* ¥ When scanning, Apple 5.25 devices are ignored, as are character devices.* ¥ Block devices with NON-removable media are still scanned, since it's*   important for some applications to get an "insert" for them the first*   time around (after WindStartUp).  May or may not scan them if they're*   already known to be online.* ¥ The call will check the tick count against the last time it was called &*   take no action if it hasn't been long enough (bypass this check if input*   flag bit 11 is set).* ¥ Will keep a table indicating which devices are considered online & offline*   and will make a series of DStatus calls looking for a status that differs*   from before.* ¥ When an eject is detected, it is reported if the flags say it should be.* ¥ When an insert is detected, it does a Volume call on the device.  If there's*   no error, continue with the scan.* ¥ If Volume returns an I/O error or unrecognized-volume error, call AlertWindow*   with the strings already in Sys.Resources (used by Standard File) asking the*   user to Eject or Initialize.* ¥ If the user elects to Eject, make the DControl Eject call to get rid of it.* ¥ If the user elects to Initialize, make the GS/OS Format call to format it*   (letting the user name the disk and specify the file system & format options*   within the Format call).* ¥ If they cancel out of the Format dialog, eject the disk and return no error.* ¥ If the format is successful, return the device number as the ResultDevNum.* ¥ If the Volume call returns a *weird* error, leave it online, return the*   device number to the caller, and return the Volume error to the caller!** If an insert or eject is reported, there is no 1-second delay enforced on the* next call.** When the volume call returns error $52, we call SendRequest($0002)* to see if anybody wants to put up a special dialog for the disk.* They get to specify eject/initialize/erase.  Low word of dataIn =* device number, offset 4 of dataOut = disposition (0=eject, 1=init,* 2=erase, $FFFF = leave the volume online and report no error).** If nobody wants to special-case it, then we put up the standard* AlertWindow with Eject/Initialize buttons (and Option-initialize* means to Erase instead).** If they click Option-Initialize on our standard dialog for error $52,* then we do an Erase instead of a Format.** When call completes, the cursor is set to the same thing it was before.* During the call, Arrow and Watch cursors are used.** ¥ NOTE -- This code only goes as high as device 127.  References to*           DevStatTable need to change if you want more.** WindStartUp calls HandleDiskInsert($2000,$0000) to initialize us.***********************************************************************HandleDiskInsert	proc export	import FlushKeyEvents	phb	phk	plb	phd	pea 0	;space/initial value for @theError	tsc	tcdfDoDeviceScan	equ $8000	;must be bit 15 (BPL!)fHandleInsertion	equ $4000fUpdateDevStatus	equ $2000fReportEjects	equ $1000fNoDelay	equ $0800fDuplicateVolume	equ $0400	;23-Apr-91 DALfCheckTapeDrives	equ $0200	;10-Oct-91 DALhdiUnreadable	equ $0100	;9-Dec-91 DALfInitialize	equ $0001	;must be bit 0@theError	equ 1@oldD	equ @theError+2@oldB	equ @oldD+2@rtl	equ @oldB+1@devNum	equ @rtl+6@flags	equ @devNum+2@resultDevNum	equ @flags+2@resultFlags	equ @resultDevNum+2	stz <@resultDevNum	stz <@resultFlags	lda <@flags	lsr a	bcc @noInit	lda #0	ldx #14@clear	sta DevStatTable,x	dex	dex	bpl @clear@noInit		lda <@flags	and #fUpdateDevStatus	beq @noUpdate	jsr @UpdateDevStatus@noUpdate	lda <@flags	bpl @noScanning	jsr @DoScanning	bra @cont@noScanning	lda <@devNum	sta <@resultDevNum@cont	lda <@flags	and #fHandleInsertion	beq @noUserStuff	jsr @PreserveCursor	jsr @HandleAnInsertion	jsr @RestoreCursor@noUserStuff	ldx <@theError	pla	;pull <@theError	pld	plb	ldy #4	jml $e10184	;ToStrip************************************************************************ PreserveCursor***********************************************************************@PreserveCursor	pha	pha	_GetCursorAdr	pla	sta @theCursor	pla	sta @theCursor+2	rts************************************************************************ RestoreCursor -- if the cursor has changed, put it back** (If it hasn't changed, avoid bogus flicker by not doing anything.)***********************************************************************@RestoreCursor	pha	pha	_GetCursorAdr	plx	pla	cmp @theCursor+2	bne @setIt	cpx @theCursor	bne @setIt	rts@setIt	pushlong @theCursor	_SetCursor	rts@theCursor	dc.l 0************************************************************************ DoScanning** If fNoDelay is clear and it's been less than a second since the* last time we polled, return without doing anything.***********************************************************************@doScanning	lda <@flags	and #fNoDelay	bne @noDelay	jsr @GetTickCount	sec	sbc PrevTime	cmp #60	;has it been a second yet?	bcs @longEnough	rts	;return, no action@longEnough@noDelay	lda #0@scanLoop	inc a	cmp #128	bcs @scanDone	jsr @ScanDeviceA	bcc @scanLoop@scanDone	jsr @GetTickCount	sta PrevTime	rts************************************************************************ UpdateDevStatus** Update our private idea of whether a device is online, or all* devices.  <@devNum is 0 or a specific device.***********************************************************************@UpdateDevStatus	lda <@devNum	bne @updateDeviceA@updateLoop	inc a	pha	jsr @updateDeviceA	pla	bcc @updateLoop	rts@updateDeviceA	cmp #128	bcs @updated	pha	jsr @GetStatusDeviceA  ;SEC=online, CLC=offline, X<>0 if done	pla	txy	bne @errorMeansOnline	jsr @SetDevStatus	clc@updated	rts@errorMeansOnline	sec	rts************************************************************************ ScanDeviceA -- see if an insert/eject happened for device A** If nothing happened, return CLC.* If we're out of devices, return SEC.* If we find an insert/eject, set <@resultDevNum and <@resultFlags*   and return SEC.** Side effect: updates the DevStatusTable to reflect the device's* new status.***********************************************************************@ScanDeviceA	pha	jsr @GetStatusDeviceA	txa	beq @stillGoing	pla	sec	;out of devices!	rts@stillGoing	bcc @nowOffline	;carry still has online status@nowOnline	lda 1,s	phy	;added 31-Jan-92 DAL (keep TheStatusWord)	jsr @LookupDevStatus	ply	;added 31-Jan-92 DAL	bcs @stillOnline; now we know it's an insert@weHaveAnInsert	sec	lda 1,s	jsr @SetDevStatus	bra @returnThisDev@nowOffline	lda 1,s	jsr @LookupDevStatus	bcc @stillOffline; now we know it's an eject	clc	lda 1,s	jsr @SetDevStatus	;mark it offline	lda <@flags	and #fReportEjects	beq @stillOffline	lda #$0001	;bit = 0 ejection	tsb <@resultFlags@returnThisDev	pla	sta <@resultDevNum	stz PrevTime	;don't make them wait for the next one!	sec	rts*** added 31-Jan-92 DAL -- If there was a disk-switched, treat online as insert@stillOnline	tya	and #1	bne @weHaveAnInsert*** end 31-Jan-92@stillOffline	pla	clc	rts************************************************************************ GetStatusDeviceA** Input: device number in A** Result: SEC=online, CLC=offline*         X<>0 if we're out of devices*         Y = device status word (bit 0 = device switched)** (Apple 5.25s are always reported as offline)***********************************************************************@GetStatusDeviceA	sta DInfoDevNum	sta DStatusDevNum	stz TheStatusWord	;added 31-Jan-92 DAL*** added 21-Nov-91 DAL -- set up pcount	lda #3	;pcount	sta DInfoParms*** end 21-Nov-91	pushlong #DInfoParms	pea $202c	;DInfo	jsl $e100b0	tax	clc	bne @gotStat	;error --> treat it as offline	jsr @GetDeviceID	clc	lda DeviceID	beq @returnStat	;say the 5.25 is offline*** 10-Oct-91 DAL -- check for Apple tape drive, only scan if we want to	cmp #$0020	;Apple tape drive	bne @notTape	lda <@flags	and #fCheckTapeDrives	clc	beq @returnStat	;return offline for tape@notTape*** end 10-Oct-91 DAL	lda DInfoChar	;characteristics	and #$0080	clc	beq @returnStat	;character device--return offline	lda DInfoChar	and #$0004	;Removable media?	sec	beq @returnStat	;if not removable, report online!	pushlong #DStatusParms	pea $202d	;DStatus	jsl $e100b0	lda TheStatusWord	and #$0010	cmp #1	;SEC = online@returnStat	ldx #0@gotStat	ldy TheStatusWord	;added 31-Jan-92 DAL	rts************************************************************************ GetDeviceID** Input: DInfoDevNum* Output: DeviceID** This routine cheats & gets a device's device_id without making a* DInfo call.  Calling DInfo with a lot of parameters does device* access, which takes too much time to do here.** $E100BE bit 15 is the GS/OS busy flag.  To make sure I have use of* GS/OS direct page, I check the bit & then keep it set while I'm* doing the work.** $01F