	lsr a	tax	pla	rts@bitmasks	dc.b $01,$02,$04,$08,$10,$20,$40,$80************************************************************************ GetTickCount -- return A = low word of tick count***********************************************************************@GetTickCount	pha	pha	_TickCount	pla	plx	rts************************************************************************ HandleAnInsertion** resultDevNum and resultFlags are valid** If there's no insert, we're done right away.***********************************************************************@goInsDone	brl @insDone@HandleAnInsertion	lda <@resultDevNum	beq @goInsDone	lda <@resultFlags	lsr a;;;	bcs @insDone	;14-Apr-91 (it's an Eject)*** 31-Jan-92 DAL -- branch was too long	bcc @notInsDone	rts@notInsDone*** 31-Jan-92 DAL; okay, we have a real insert -- do a DInfo and Volume call	lda <@resultDevNum	sta DInfoDevNum*** added 21-Nov-91 DAL -- set up large pcount	lda #8	;pcount	sta DInfoParms*** end 21-Nov-91	pushlong #DInfoParms	pea $202c	;DInfoGS	jsl $e100b0	bcs @insDone*** added 31-Jan-92 DAL -- Never handle a Tape Drive insertion	lda device_id	cmp #$0020	;Apple tape drive	beq @insDone*** end 31-Jan-92*** added 9-Dec-91 DAL -- check hdiUnreadable bit, pretend we got I/O error	lda <@flags	and #hdiUnreadable	;simulate an I/O error	beq @notUnreadable	lda #$27	bra @volumeErr@notUnreadable*** end 9-Dec-91; try making a volume call, see if we get an error	pushlong #VolumeParms	pea $2008	;VolumeGS	jsl $e100b0	bcs @volumeErr*** added 2-Dec-91 DAL -- after successful Volume call, try GetFileInfo	pushlong #gfiParms	pea $2006	jsl $e100b0	bcs @volumeErr*** end 2-Dec-91	lda <@flags	and #fDuplicateVolume	beq @insDone	lda #$57@volumeErr	cmp #$2f	;offline?	beq @insDone	cmp #$27	beq @ioError	cmp #$52	bne @not52	brl @badFileSystem@not52	cmp #$57	;duplicate volume	bne @notDupVol	jsr @RenameVolume	bcc @insDone	;24-Oct-91 DAL	brl @handleDisposition  ;24-Oct-91 DAL (was bra @insDone)@notDupVol*** 28-Oct-92 DAL -- treat $51 (directory damaged) like $5A	cmp #$0051	beq @is5a*** end 28-Oct-92*** added 2-Dec-91 DAL -- treat $46 (file not found) like $5A (damaged disk)	cmp #$0046	bne @not46@is5a	lda #$005a@not46*** end 2-Dec-91*** 14-Nov-91 DAL	cmp #$5A	;disk damaged (especially from HFS)	bne @not5A	brl @diskDamaged@not5A*** end 14-Nov-91; unknown error -- return it to the caller	sta <@theError@insDone	rts** Handle I/O error*@ioError	pea $4033	;bad disk + defer	_SysBeep2	lda #$0096	jsr @CallAlertWindow	dec a	bmi @EjectThatThang	_WaitCursor	pushlong #FormatParms	pea $2024	;Format	jsl $e100b0	bcs @ioErr2	brl @didFormat@ioErr2	tay	beq @EjectThatThang	;Cancel (error 0)*** added 10-Oct-91 DAL -- special-case error $21 for a 3.5" disk@handleFmtError	cmp #$0021	bne @not21	ldx Device_id	cpx #$0017	;MFM disk?	beq @is21	dex	;is it $0001 = 3.5"?	bne @not21@is21	lda #$0099	;special error for HandleDiskInsert (wrong media)@not21*** end 10-Oct-91 DAL	bra @ErrorAndEject** ErrorAndEject** Input:  A = error code, <@resultDevNum = device number*@ErrorAndEject	pha	;space for result	pea $0020	;substitution type + flags (button positions)	pea 0	pea 0	;substitution array	pha	;error code	jsr doInitCursor	;14-Nov-91 DAL	_ErrorWindow	pla	;button number (ignore)** Eject device <@resultDevNum (and zero it out)*@EjectThatThang	lda <@resultDevNum	sta EjectDevNum	sta DStatusDevNum	pushlong #EjectParms	PushWord #$202E		;_DControl	jsl $e100b0	lda <@resultDevNum	;18-Apr-91 DAL	jsr NotifyEjecting	;8-Jan-92	jsr @UpdateDeviceA	;18-Apr-91 DAL	lda <@resultDevNum	clc	jsr @SetDevStatus@noMarkEject	stz <@resultDevNum	rts*** added 14-Nov-91 DAL** Handle a disk-damaged error (14-Nov-91 DAL)*@diskDamaged	jsr doInitCursor	jsr @futzWStrings	pha	;space for button result	pea $00A5	;22-Nov-91 DAL	pushlong #mySubstitutions	pushlong #$07FF0E03	;damaged-disk message in Sys.Res	_AlertWindow	jsr @unfutzWStrings	pla	beq @dmgZero	jsr @computeInitErase  ;option-init --> erase@dmgZero	bra @gotResponse@unfutzWStrings	lda FormatDeviceName   ;make WStrings into PStrings	xba	sta FormatDeviceName	lda VolumeName+1	xba	inc a	sta VolumeName	lda #$3a	sep #$20	sta VolumeName+2	rep #$20	rts*** end 14-Nov-91 DAL** Handle unknown-file-system error*@badFileSystem	pea $4033	;bad disk + defer	_SysBeep2; try SendRequest(unknownDisk,devnum,result)	pea $0002	;systemSaysUnknownDisk	pea $8000	;how=$8000 (send to one)	pea 0	pea 0	;target=nil	pea 0	;high word of dataIn	pei <@resultDevNum	pushlong #srqDataOut	_SendRequest	lda srqDataOut+4	bcc @gotResponse	lda #$0097	jsr @CallAlertWindow@handleDisposition@gotResponse	tay	;added 13-Apr-91 DAL:	bmi @outtaHere	;  ...negative from SRQ = leave online!	dec a	bmi @EjectThatThang0	pushlong #FormatParms	dec a	bmi @FormatIt@EraseIt	pea $2025	bra @together@FormatIt	pea $2024@together	jsl $e100b0	bcc @didFormat	tay	beq @EjectThatThang0	brl @handleFmtError	;24-Oct-91 DAL@didFormat	lda #$0002	;bit 1 = they just formatted this	tsb <@resultFlags@outtaHere	rts@EjectThatThang0	brl @EjectThatThang** CallAlertWindow** Call AlertWindow & see what they want to do.** Return in A: 0=Eject, 1=Initialize, 2=Erase, $ffff = leave online, no error*@CallAlertWindow	pha	;save error number	sta @theErrorNumber	;10-Dec-91 DAL	lda FormatDeviceName	xba	sta FormatDeviceName	plx	;get error number	pha	;space for ErrorWindow result	pea $0021	;Pascal substitution string	pushlong #FormatDeviceName+1	phx	jsr doInitCursor	;14-Nov-91 DAL	_ErrorWindow*** added 10-Dec-91 DAL -- re-lock the rErrorString handle to make it stay around	pha	pha	;space for LoadResource	pea $8020	;rErrorString	pea $07FF	lda @theErrorNumber	pha	_LoadResource	pla	pla	;ignore result (side effect locks handle)*** end 10-Dec-91	lda FormatDeviceName	xba	sta FormatDeviceName	pla	;ErrorWindow result	beq @zero; if they held down the Option key, turn the Init request into an Erase request	jsr @computeInitErase@zero	rts@computeInitErase	ldx #1	;anticipate Init	lda >$e0c025	and #$0040	beq @notErase	inx	;2=Erase@notErase	txa	rts@theErrorNumber	dc.w 0	;10-Dec-91 DAL************************************************************************ RenameVolume** Prompt the user to rename or eject the duplicate volume in device* @resultDevNum.** The DInfoParms block is already set up from a DInfo call (pcount=8).* The VolumeParms block is also set up from a Volume call.  The* volume name is valid even if the call returned error $57.** If carry is set on return:*   A=0: eject, 1=Init, 2=Erase, $FFFF=leave online***********************************************************************@RenameVolume*** added 24-Oct-91 DAL -- see if we can possibly rename this volume	lda volCharacteristics	;from Volume call	tax	and #$0040	;can we ever write this device?	beq @mustEject	txa	lsr a	;$0001=read-only FST	bcs @cantRename	lda #$ffff	sta gfiAccess	;in case of strange error, assume full access	pushlong #getFileInfoParms	pea $2006	;GetFileInfo	jsl $e100b0	lda gfiAccess	and #$0040	;Rename enabled?	beq @cantRename*** added 27-Oct-91 DAL;; check for AppleShare (special case--GetFileInfo can return duplicate-volume,; in which case the gfiAccess is not valid);	lda volDeviceID	cmp #$001E	;Is it AppleShare?	beq @cantRename*** end 27-Oct-91	bra @RenameIsPossible*** can't rename--either eject, or eject/initialize@cantRename	lda volCharacteristics	and #$0008	;can we format this device?	beq @mustEject*** it's a read-only FST -- give can't rename-->Eject or Initialize msg@ejectOrInit	jsr @futzWStrings	pha	;space	pea $00A5	;22-Nov-91 DAL	pushlong #mySubstitutions	pushlong #$07FF0E01	jsr doInitCursor	;14-Nov-91 DAL	_AlertWindow	pla	beq @ejectIt	lda FormatDeviceName   ;make PString back into WString	xba	sta Fo