 end 21-Nov-91	_LoadResource	phd	tsc	tcd	ldy #2	lda [3],y	tax	lda [3]	sta 3	stx 5	pld*** end 10-Dec-91	pea $800e	;resource type	_NewWindow2	;leave window pointer on stack	pea $4052	;Stop-icon sound	_SysBeep2; set the edit line maximum length from the JudgeName maximum-length value	pha	pha	;space for GetCtlTitle	pha	pha	;space for GetCtlHandleFromID	pha	pha	;space for FrontWindow	_FrontWindow	pushlong #3	;edit line control ID	_GetCtlHandleFromID	;got control handle	_GetCtlTitle	;got Line Edit record handle	phd	tsc	tcd	ldy #2	lda [3]	tax	lda [3],y	sta 5	stx 3	;derefed line edit record	ldy #6	lda jnMaxLength	cmp #32	bcs @whoops	sta [3],y	;stuff in a new maximum length@whoops	pld	pla	pla	lda TheNewVolumeName	xba	sta TheNewVolumeName  ;change to pstring	pha	pha	_FrontWindow	pushlong #3	;edit line control ID	pushlong #TheNewVolumeName+1	_SetLETextByID	lda TheNewVolumeName	xba	sta TheNewVolumeName*** @modalLoop -- come back here for another try at renaming the thing@modalLoop	pha	pha	;space for DoModalWindow result	pushlong #myEventRec	ldx #0	phx	phx	;update routine	pushlong #myEventFilter+$80000000 ;bit 31 of event hook = do Apple-period-->ESC	phx	phx	;beep proc	pea $0009	;noScrapForLE, use I-Beam cursor	_DoModalWindow	pla	plx	cmp #4	;Eject button?	bne @notEject; eject the device and update its status@doEject	lda <@resultDevNum	sta EjectDevNum	pushlong #EjectParms	pea $202E	;_DControl	jsl $e100b0	lda <@resultDevNum	jsr NotifyEjecting	;added 8-Jan-92 DAL	jsr @UpdateDeviceA	stz <@resultDevNum	;don't tell the caller about it	brl @done@notEject	cmp #5	;Rename button?	beq @hitRename	cmp #3	;Edit line control?	bne @modalLoop	pha	;space for LEGetTextLen	pha	pha	;space for GetCtlTitle	pha	pha	;space for GetCtlHandleFromID	pha	pha	;space for FrontWindow	_FrontWindow	pea 0	pea 3	;ctl ID (long)	_GetCtlHandleFromID	_GetCtlTitle	_LEGetTextLen	tax	;X=0	pla	bne @hiliteX	ldx #$00ff@hiliteX	phx	pha	pha	;space for GetCtlHandleFromID	pha	pha	;space for FrontWindow	_FrontWindow	pushlong #5	;Rename button control ID	_GetCtlHandleFromID	_HiliteControl	brl @modalLoop@hitRename	jsr doInitCursor	;14-Nov-91 DAL	pha	pha	_FrontWindow	pushlong #3	;Edit Line Control ID	pushlong #TheNewVolumeName+2	_GetLETextByID	lda TheNewVolumeName+2	and #$00ff	inc a	sta TheNewVolumeName	lda #$3a	sep #$20	sta TheNewVolumeName+2 ;put a colon on the beginning	rep #$20	lda FormatDeviceName	xba	sta FormatDeviceName; @@@ should do a JudgeName here	pushlong #RenameParms	pea $2004	;ChangePathGS	jsl $e100b0	tax	lda FormatDeviceName	xba	sta FormatDeviceName	txa	bcc @done	pha	;space	ldx #0	phx	phx	phx	pha	;error number	_ErrorWindow	pla	;get rid of button number	brl @modalLoop	;20-May-91 DAL@done	_CloseWindow	jsr FlushKeyEvents	;4-Oct-91 DAL@abort	_SetCursor	;restore cursor	_ShowCursor	;because typing into the Edit Line obscured it!	_SetCtlParamPtr	;restore old substitution array	clc	;don't format	rtsmySubstitutions	dc.l VolumeName+2   ;volume name	dc.l FormatDeviceName+1   ;disk namemyEventRec	ds.b 46RenameParms	dc.w 3	;was 2 (5-Dec-91 DAL)	dc.l FormatDeviceName	dc.l TheNewVolumeName	dc.w $8000	;Trust me!  (5-Dec-91 DAL)NewVolNameResultBuff dc.w 37TheNewVolumeName	ds.b 35JudgeNameParms	dc.w 6	;pcountjnFileSystem	dc.w 0	;file sys id	dc.w 1	;name type = volume name	dc.l 0	;syntax string (result)jnMaxLength	dc.w 0	;max name length	dc.l NewVolNameResultBuff	dc.w 0	;name flags (result)getFileInfoParms	dc.w 2	;just get the access	dc.l FormatDeviceNamegfiAccess	dc.w 0************************************************************************ NotifyEjecting -- send a SendRequest(systemSaysEjectingDev) so*                   that EasyMount will not try to open a window*                   for a duplicate volume.** Input:  device number in A (preserved)** systemSaysEjectingDev:  dataIn low word = devNum.  High word and*                         dataOut are reserved.** 8-Jan-92 DAL***********************************************************************NotifyEjecting	pha	;preserve devnum	ldx #0	pea systemSaysEjectingDev	phx	;send to all	phx	phx	;target=all	phx	pha	;dataIn = devnum	phx	phx	;dataOut = nil	_SendRequest	pla	;restore devnum	rts************************************************************************ DoModalWindow event filter for the Rename-volume dialog.** Changes keypresses of ":" and up/down arrows into null events,* Apple-e and Apple-E into escape (Eject).** For an update event, draws the Disk icon in the top left.***********************************************************************MyEventFilter	phd	tsc	tcd	lda [6]	cmp #3	beq @key	cmp #5	bne @notKey@key	ldy #2	;message	lda [6],y	and #$00ff	cmp #$000a	beq @killKey	cmp #$000b	beq @killKey	cmp #$003a	;Colon?	bne @notColon@killKey	lda #0	sta [6]	;make it a null event	bra @exit	@notColon	ldy #14	;modifiers	lda [6],y	and #$0100	;Apple key down?	beq @notKey	;nope	ldy #2	;check message field for character	lda [6],y	and #$00df	cmp #$0045	;'e' or 'E'	bne @notKey	lda #$001B	;Escape for Eject	sta [6],y*** added 22-Nov-91 DAL -- handle updates	bra @exit@notKey	cmp #6	;Update event	bne @notUpdate	pha	pha	_FrontWindow	pla	plx	ldy #2	;offset to Message field (window ptr)	cmp [6],y	bne @notMyUpdate	iny	iny	txa	cmp [6],y	bne @notMyUpdate	jsr pushIconPtr	pea 0	;mode 0	pea 20	;X=20	pea 7	;Y=7	_DrawIcon@notMyUpdate@notUpdate*** end 22-Nov-91@exit	pld	lda 2,s	sta 2+4,s	lda 1,s	sta 1+4,s	pla	pla	rtl*** added 22-Nov-91 DAL -- push ptr to 640 or 320 disk iconpushIconPtr	pha	pha	pea $8001	;rIcon	pea $07FF	pha	_GetMasterSCB	pla;;;	ldy #$0005	;anticipate 640	ldy #$0003	;640 note icon (19-Feb-93 DAL)	and #$0080	bne @640;;;	ldy #$0105	ldy #$0103	;320 note icon (19-Feb-93 DAL)@640	phy	_LoadResource	phd	tsc	tcd	ldy #2	lda [3],y	tax	lda [3]	sta <3	stx <5	pld	;result is now on stack	ply	pla	;AY=resul	plx	;RTS address	pha	phy	;pushed result	phx	;pushed RTS address	rts*** end 22-Nov-91**********************************************************************PrevTime	dc.w 0DevStatTable	dc.w 0,0,0,0,0,0,0,0  ;128 status bits!DInfoParms	dc.w $7777	;caller must store 3 or 8 (21-Nov-91 DAL)DInfoDevNum	dc.w 0	;device number	dc.l FormatDeviceBufferDInfoChar	dc.w 0	dc.l 0	;total blocks	dc.w 0	;slot num	dc.w 0	;unit num	dc.w 0	;versiondevice_id	dc.w 0DeviceID	dc.w 0	;dev_id from skanky @GetDeviceIDDStatusParms	dc.w 5DStatusDevNum	dc.w 0	dc.w 0	;status code 0	dc.l TheStatusWord	dc.l 2	;request count	dc.l 0	;transfer countTheStatusWord	dc.w 0VolumeParms	dc.w 8	dc.l FormatDeviceName	dc.l VolumeNameBuffer	dc.l 0	;blocks	dc.l 0	;free blocksvolFileSys	dc.w 0	;file system (valid for dup-vol err if 8 parms!)	dc.w 0	;block sizevolCharacteristics	dc.w 0	;device/filesys characteristicsvolDeviceID	dc.w 0	;device ID*** added 2-Dec-91 DALgfiParms	dc.w 2	;2 parameters	dc.l VolumeName	dc.w 0	;access*** end 2-Dec-91FormatParms	dc.w 1	;just one parameter	dc.l FormatDeviceNameFormatDeviceBuffer	dc.w 36FormatDeviceName	ds.b 34VolumeNameBuffer	dc.w 36VolumeName	ds.b 34EjectParms	dc.w 5EjectDevNum	dc.w 0	dc.w 2	;control code	dc.l 0	;control list	dc.l 0	;request count	dc.l 0	;transfer countsrqDataOut	dc.w 0,0,0	;recvCount, reserved, disposition**********************************************************************	EndP************************************************************************ FlushKeyEvents -- kill all pending keyDown and autoKey events (DAL)***********************************************************************FlushKeyEvents	proc export	pha	;space for result	pea $0028	;keyDown and autoKey events	pea $0000	;don't stop, kill 'em all	_FlushEvents	pla	;discard result flag	rts	EndP****************************************************************** UpdateWindow $6C0E -- new call 6-Mar-92 DAL for 6.0.1** Input:*   push flags (word)*   push window pointer (long)** Flags:*   bit 15 = window's expected environment may not be set up ("background update")*            (requires wContDraw bit 31, saying that the wContDraw routine can take*             care of itself)*   bit 14 = GS/OS is *not* available or not safe to call*            (requires wContDraw bit 30, saying that the wContDraw doesn't need to*             call GS/OS)*   bits 13-0 = reserved, use 0*****************************************************************UpdateWindow	proc export	import longCall	phd	pha	pha	;space for drawPtr	tsc	tcd@drawPtr	equ 1@oldD	equ @drawPtr+4@rtls	equ @oldD+2@window	equ @rtls+6@flags	equ @window+4*** added 23-Mar-93 DAL -- never background-update a System window (that should only***    happen from a System window's code, called from inside SystemEvent, so the***    background-update flag will not be set).	lda <@flags	bpl @notBackground	pha	pei <@window+2	pei <@window	_GetSysWFlag	pla	bpl @notSysWind	ldx #cantUpdateErr	bra @errorExit@notSysWind@notBackground*** end 23-Mar-93 DAL	pha	pha	;space for GetContentDraw	pei <@window+2	pei <@window	_GetContentDraw	pla	sta <@drawPtr	pla	sta <@drawPtr+2	ldx #cantUpdateErr	lda <@drawPtr+1	beq @errorExit*** If GS/OS is busy, force flag bit 14	lda >$e100be	bpl @notBusy	lda #$4000	tsb <@flags@notBusy*** Any bits in <flags require bits in wContDraw to be set, or we can't update.	lda <@drawPtr+2	eor #$ffff	and <@flags	ldx #cantUpdateErr	and #$ff00	bne @errorExit	lda <@window+2	ldx <@window	pha	phx	;for EndUpdate	pha	phx	;for StartDrawing	pha	phx	;for BeginUpdate	_BeginUpdate	_StartDrawing	ldx <@drawPtr+1	lda <@drawPtr	jsl longCall	lda #0	pha	pha	_SetOrigin	_EndUpdate@noError	ldx #0	;no error@errorExit	pla	pla	pld	ldy #6	;strip 6 bytes	jml $e10184	;ToStrip	EndP	END